import { OAuthButton } from '@refy-design/web';
import { oauthProviders } from '@refy-design/web';
import { useState } from 'react';
export function Example() {
  const [selected, setSelected] = useState('');
  return (
    <div
      style={{
        display: 'grid',
        gap: 'var(--space-4)',
        maxWidth: 420,
        width: '100%',
      }}
    >
      {(Object.keys(oauthProviders) as (keyof typeof oauthProviders)[]).map(
        (provider) => (
          <OAuthButton
            key={provider}
            provider={provider}
            block
            onClick={() => setSelected(oauthProviders[provider])}
          />
        ),
      )}
      <p role="status">
        {selected
          ? `${selected} selected. Connect the callback to your project's OAuth flow.`
          : 'Choose a provider. Local demo.'}
      </p>
    </div>
  );
}

